import { Link } from 'react-router-dom';
import '../styles/Home.css';

const features = [
  { icon: '🎙️', title: 'AI-Powered Questions',  desc: 'Dynamic questions tailored to your role and experience level. No two sessions are the same.' },
  { icon: '⚡',  title: 'Real-Time Feedback',    desc: 'Instant analysis of your answers — clarity, confidence, and keyword coverage scored live.' },
  { icon: '📊',  title: 'Progress Analytics',    desc: 'Session history, performance trends, and personalised tips to track your growth over time.' },
  { icon: '🧠',  title: 'Adaptive Difficulty',   desc: 'The system adjusts question complexity based on your performance to keep you challenged.' },
  { icon: '🔒',  title: 'Private Practice',      desc: 'All sessions are private by default. Practice as many times as you need.' },
  { icon: '🌐',  title: 'Any Role, Any Domain',  desc: 'Covers software engineering, product, design, finance, consulting, data science, and more.' },
];

function Home() {
  return (
    <main className="page home">
      <section className="home__hero">
        <div className="home__hero-inner">
          <h1 className="home__heading fade-up">
            Welcome to <span className="accent">AI Mock Interview</span> System
          </h1>
          <p className="home__desc fade-up-2">
            Practice technical and behavioural interviews with an AI that gives
            real-time feedback, tracks your progress, and helps you land the role you want.
          </p>
          <div className="home__actions fade-up-3">
            <Link to="/about" className="btn-primary">Start Interview →</Link>
            <Link to="/about" className="btn-ghost">Learn More</Link>
          </div>
        </div>
      </section>
    </main>
  );
}

export default Home;
